import {
  Injectable,
  Logger,
  OnApplicationBootstrap,
  OnApplicationShutdown,
  OnModuleDestroy,
  Optional,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { InjectConnection, InjectModel } from '@nestjs/mongoose';
import { SchedulerRegistry } from '@nestjs/schedule';
import { createHmac, randomUUID } from 'node:crypto';
import { Connection, Model, Types } from 'mongoose';
import { AuthIdentifierRepairKeyPolicyService } from './auth-identifier-repair-key-policy.service';
import {
  AuthIdentifierAssignmentStatus,
  AuthIdentifierOperationAssignment,
  AuthIdentifierOperationCleanupStatus,
  AuthIdentifierOperationDocument,
  AuthIdentifierOperationModelName,
  AuthIdentifierOperationResultOutcome,
  AuthIdentifierOperationStatus,
  AuthIdentifierOperationType,
} from './schemas/auth-identifier-operation.schema';
import {
  AuthIdentifierRepairBatchDocument,
  AuthIdentifierRepairBatchModelName,
} from './schemas/auth-identifier-repair-batch.schema';
import {
  AuthIdentifierDocument,
  AuthIdentifierModelName,
  AuthIdentifierPendingAction,
  AuthIdentifierStatus,
} from './schemas/auth-identifier.schema';
import {
  SecurityActivityActorType,
  SecurityActivityOutcome,
} from './schemas/security-activity-event.schema';
import { SecurityActivityService } from './security-activity.service';

const SCHEDULE_NAME = 'auth-identifier-reconciliation';
const CLOCK_SKEW_SECONDS = 5;
const DEFAULT_LEASE_SECONDS = 300;
const DEFAULT_INTERVAL_SECONDS = 60;
const DEFAULT_BATCH_SIZE = 100;
const DEFAULT_RETENTION_DAYS = 90;
const DEFAULT_MAX_ASSIGNMENTS = 20;
const REQUIRED_AUTH_MIGRATION = '003';
const MIGRATION_RECORDS_COLLECTION = 'migration_records';

const RECONCILABLE_STATUSES = [
  AuthIdentifierOperationStatus.Pending,
  AuthIdentifierOperationStatus.Applying,
  AuthIdentifierOperationStatus.Compensating,
  AuthIdentifierOperationStatus.Finalizing,
  AuthIdentifierOperationStatus.FailedRetryable,
] as const;

const TERMINAL_STATUSES = [
  AuthIdentifierOperationStatus.Completed,
  AuthIdentifierOperationStatus.FailedTerminal,
] as const;

export interface AuthIdentifierReconciliationResult {
  examined: number;
  claimed: number;
  processed: number;
  skippedMissingKey: number;
}

@Injectable()
export class AuthIdentifierReconciliationService
  implements OnApplicationBootstrap, OnApplicationShutdown, OnModuleDestroy
{
  private readonly logger = new Logger(
    AuthIdentifierReconciliationService.name,
  );
  private readonly instanceId = randomUUID();
  private activeRun?: Promise<AuthIdentifierReconciliationResult>;
  private scheduled = false;
  private readinessProbe?: NodeJS.Timeout;
  private readinessStart?: Promise<boolean>;
  private lifecycleGeneration = 0;
  private stopped = false;

  constructor(
    @InjectModel(AuthIdentifierOperationModelName)
    private readonly operationModel: Model<AuthIdentifierOperationDocument>,
    @InjectModel(AuthIdentifierModelName)
    private readonly identifierModel: Model<AuthIdentifierDocument>,
    @InjectModel(AuthIdentifierRepairBatchModelName)
    private readonly repairBatchModel: Model<AuthIdentifierRepairBatchDocument>,
    private readonly keyPolicy: AuthIdentifierRepairKeyPolicyService,
    private readonly securityActivityService: SecurityActivityService,
    private readonly configService: ConfigService,
    @Optional() private readonly schedulerRegistry?: SchedulerRegistry,
    @Optional()
    @InjectConnection()
    private readonly connection?: Connection,
  ) {}

  async onApplicationBootstrap(): Promise<void> {
    if (this.stopped) {
      this.stopped = false;
      this.lifecycleGeneration += 1;
    }
    let started = false;
    try {
      started = await this.startWhenMigrationsReady();
    } catch {
      this.logger.warn('Auth identifier migration readiness check failed');
    }
    if (!started) {
      this.registerReadinessProbe();
    }
  }

  private startWhenMigrationsReady(): Promise<boolean> {
    if (!this.readinessStart) {
      const generation = this.lifecycleGeneration;
      this.readinessStart = this.startWhenMigrationsReadyOnce(generation).finally(
        () => {
          this.readinessStart = undefined;
        },
      );
    }
    return this.readinessStart;
  }

  private async startWhenMigrationsReadyOnce(
    generation: number,
  ): Promise<boolean> {
    if (this.stopped || this.scheduled || !(await this.requiredMigrationsReady())) {
      return this.scheduled;
    }
    if (
      this.stopped ||
      generation !== this.lifecycleGeneration ||
      this.scheduled
    ) {
      return this.scheduled;
    }
    this.registerSchedule();
    if (this.stopped || generation !== this.lifecycleGeneration || !this.scheduled) {
      return false;
    }
    try {
      await this.reconcileOnce();
    } catch {
      this.logger.warn('Auth identifier reconciliation startup pass failed');
    }
    return true;
  }

  async onModuleDestroy(): Promise<void> {
    // Stop producers and drain database work before Mongoose's shutdown hook.
    this.onApplicationShutdown();
    await this.activeRun?.catch(() => {
      this.logger.warn(
        'Auth identifier reconciliation interrupted during shutdown',
      );
    });
  }

  onApplicationShutdown(): void {
    this.stopped = true;
    this.lifecycleGeneration += 1;
    if (this.readinessProbe) {
      clearInterval(this.readinessProbe);
      this.readinessProbe = undefined;
    }
    if (
      this.scheduled &&
      this.schedulerRegistry?.doesExist('interval', SCHEDULE_NAME)
    ) {
      this.schedulerRegistry.deleteInterval(SCHEDULE_NAME);
    }
    this.scheduled = false;
  }

  reconcileOnce(): Promise<AuthIdentifierReconciliationResult> {
    if (!this.activeRun) {
      this.activeRun = this.runBoundedPass().finally(() => {
        this.activeRun = undefined;
      });
    }
    return this.activeRun;
  }

  async renewLease(operationId: string): Promise<boolean> {
    const updated = await this.operationModel.findOneAndUpdate(
      {
        operationId,
        leaseOwner: this.instanceId,
        $expr: { $gt: ['$leaseExpiresAt', '$$NOW'] },
      },
      [
        {
          $set: {
            leaseExpiresAt: {
              $dateAdd: {
                startDate: '$$NOW',
                unit: 'second',
                amount: this.leaseSeconds,
              },
            },
            updatedAt: '$$NOW',
          },
        },
      ],
      { returnDocument: 'after', updatePipeline: true },
    );
    return Boolean(updated);
  }

  private registerSchedule(): void {
    if (!this.schedulerRegistry || this.scheduled) {
      return;
    }

    const interval = setInterval(() => {
      void this.reconcileOnce().catch(() => {
        this.logger.warn(
          'Scheduled auth identifier reconciliation pass failed',
        );
      });
    }, this.intervalSeconds * 1000);
    interval.unref();
    this.schedulerRegistry.addInterval(SCHEDULE_NAME, interval);
    this.scheduled = true;
  }

  private async runBoundedPass(): Promise<AuthIdentifierReconciliationResult> {
    const candidates = await this.operationModel
      .find(
        this.candidateFilter(new Date(Date.now() - CLOCK_SKEW_SECONDS * 1000)),
      )
      .sort({ updatedAt: 1, _id: 1 })
      .limit(this.batchSize * 2)
      .lean()
      .exec();
    const result: AuthIdentifierReconciliationResult = {
      examined: candidates.length,
      claimed: 0,
      processed: 0,
      skippedMissingKey: 0,
    };

    for (const candidate of candidates) {
      if (result.claimed >= this.batchSize) {
        break;
      }

      if (!this.repairKeyAvailable(candidate)) {
        result.skippedMissingKey += 1;
        continue;
      }

      const operation = await this.claim(candidate._id);
      if (!operation) {
        continue;
      }

      result.claimed += 1;
      try {
        await this.process(operation);
        result.processed += 1;
      } catch {
        this.logger.warn('Auth identifier reconciliation operation failed');
      } finally {
        await this.releaseLease(operation.operationId);
      }
    }

    return result;
  }

  private candidateFilter(clientCutoff: Date): Record<string, unknown> {
    return {
      $and: [
        {
          $or: [
            { status: { $in: RECONCILABLE_STATUSES } },
            {
              status: { $in: TERMINAL_STATUSES },
              cleanupStatus: AuthIdentifierOperationCleanupStatus.Pending,
            },
          ],
        },
        {
          $or: [
            { leaseExpiresAt: { $exists: false } },
            { leaseExpiresAt: { $lte: clientCutoff } },
          ],
        },
      ],
    };
  }

  private repairKeyAvailable(
    operation: Pick<
      AuthIdentifierOperationDocument,
      'operationType' | 'manifestKeyVersion'
    >,
  ): boolean {
    if (operation.operationType !== AuthIdentifierOperationType.OfflineRepair) {
      return true;
    }
    return (
      this.keyPolicy.repairWorkerDecision(operation.manifestKeyVersion).allowed &&
      Boolean(this.keyPolicy.getKeyMaterial(operation.manifestKeyVersion))
    );
  }

  private async claim(
    operationId: Types.ObjectId,
  ): Promise<AuthIdentifierOperationDocument | null> {
    return this.operationModel.findOneAndUpdate(
      {
        _id: operationId,
        $and: [
          {
            $or: [
              { status: { $in: RECONCILABLE_STATUSES } },
              {
                status: { $in: TERMINAL_STATUSES },
                cleanupStatus: AuthIdentifierOperationCleanupStatus.Pending,
              },
            ],
          },
          {
            $or: [
              { leaseExpiresAt: { $exists: false } },
              {
                $expr: {
                  $lte: [
                    '$leaseExpiresAt',
                    {
                      $dateSubtract: {
                        startDate: '$$NOW',
                        unit: 'second',
                        amount: CLOCK_SKEW_SECONDS,
                      },
                    },
                  ],
                },
              },
            ],
          },
        ],
      },
      [
        {
          $set: {
            leaseOwner: this.instanceId,
            leaseExpiresAt: {
              $dateAdd: {
                startDate: '$$NOW',
                unit: 'second',
                amount: this.leaseSeconds,
              },
            },
            updatedAt: '$$NOW',
          },
        },
      ],
      { returnDocument: 'after', updatePipeline: true },
    );
  }

  private async process(
    operation: AuthIdentifierOperationDocument,
  ): Promise<void> {
    if (
      TERMINAL_STATUSES.includes(
        operation.status as (typeof TERMINAL_STATUSES)[number],
      )
    ) {
      if (
        operation.cleanupStatus === AuthIdentifierOperationCleanupStatus.Pending
      ) {
        await this.cleanup(operation);
      }
      return;
    }

    await this.attachMissingReservationReferences(operation);

    switch (operation.status) {
      case AuthIdentifierOperationStatus.Pending:
        await this.transition(
          operation.operationId,
          AuthIdentifierOperationStatus.Pending,
          AuthIdentifierOperationStatus.Applying,
        );
        break;
      case AuthIdentifierOperationStatus.FailedRetryable:
        await this.transition(
          operation.operationId,
          AuthIdentifierOperationStatus.FailedRetryable,
          operation.assignments.some((item) => item.status === 'compensated')
            ? AuthIdentifierOperationStatus.Compensating
            : AuthIdentifierOperationStatus.Applying,
        );
        break;
      case AuthIdentifierOperationStatus.Applying:
        await this.recoverApplying(operation);
        break;
      case AuthIdentifierOperationStatus.Compensating:
        await this.recoverCompensating(operation);
        break;
      case AuthIdentifierOperationStatus.Finalizing:
        await this.finalize(operation);
        break;
      default:
        await this.failInvalidOperation(operation);
    }
  }

  private async requiredMigrationsReady(): Promise<boolean> {
    if (!this.connection?.db) {
      return false;
    }
    return Boolean(
      await this.connection.db
        .collection(MIGRATION_RECORDS_COLLECTION)
        .findOne({ version: REQUIRED_AUTH_MIGRATION }),
    );
  }

  private registerReadinessProbe(): void {
    if (this.stopped || this.readinessProbe || this.scheduled) {
      return;
    }
    this.readinessProbe = setInterval(() => {
      void this.runReadinessProbe();
    }, this.intervalSeconds * 1000);
    this.readinessProbe.unref();
  }

  private async runReadinessProbe(): Promise<void> {
    try {
      if (!(await this.startWhenMigrationsReady())) {
        return;
      }
      if (this.readinessProbe) {
        clearInterval(this.readinessProbe);
        this.readinessProbe = undefined;
      }
    } catch {
      this.logger.warn('Auth identifier migration readiness check failed');
    }
  }

  private async failInvalidOperation(
    operation: AuthIdentifierOperationDocument,
  ): Promise<void> {
    const eventId =
      await this.securityActivityService.recordIdentifierOperationTerminal({
        operationId: operation.operationId,
        operationType: operation.operationType,
        terminalStatus: AuthIdentifierOperationStatus.FailedTerminal,
        actor: {
          actorType:
            operation.requestedBy.subjectType === 'member'
              ? SecurityActivityActorType.Member
              : SecurityActivityActorType.Staff,
          actorId: operation.requestedBy.subjectId,
        },
        outcome: SecurityActivityOutcome.Failure,
        reasonCategory: 'identifier-operation-invalid-state',
      });
    await this.operationModel.findOneAndUpdate(
      {
        operationId: operation.operationId,
        status: operation.status,
        leaseOwner: this.instanceId,
      },
      [
        {
          $set: {
            status: AuthIdentifierOperationStatus.FailedTerminal,
            result: {
              outcome: AuthIdentifierOperationResultOutcome.Failure,
              reasonCategory: 'identifier-operation-invalid-state',
              httpStatus: 409,
            },
            terminalEventId: eventId,
            terminalEventRecordedAt: '$$NOW',
            completedAt: '$$NOW',
            expiresAt: {
              $dateAdd: {
                startDate: '$$NOW',
                unit: 'day',
                amount: this.retentionDays,
              },
            },
            updatedAt: '$$NOW',
          },
        },
      ],
      { returnDocument: 'after', updatePipeline: true },
    );
  }

  private async attachMissingReservationReferences(
    operation: AuthIdentifierOperationDocument,
  ): Promise<void> {
    const reservations = await this.identifierModel
      .find({ pendingOperationId: operation.operationId })
      .limit(this.maxAssignments + 1)
      .lean()
      .exec();
    if (reservations.length > this.maxAssignments) {
      await this.transition(
        operation.operationId,
        operation.status,
        AuthIdentifierOperationStatus.FailedRetryable,
      );
      return;
    }

    for (const reservation of reservations) {
      const assignment = operation.assignments.find(
        (item) =>
          !item.targetReservationId &&
          item.subjectType === reservation.subjectType &&
          item.subjectId === reservation.subjectId &&
          String(item.action) === String(reservation.pendingAction),
      );
      if (!assignment) {
        continue;
      }

      const correlation = this.correlationFor(
        reservation.normalizedIdentifier,
        operation.manifestKeyVersion,
      );
      await this.operationModel.updateOne(
        {
          operationId: operation.operationId,
          'assignments.assignmentId': assignment.assignmentId,
          'assignments.targetReservationId': { $exists: false },
          leaseOwner: this.instanceId,
        },
        {
          $set: {
            'assignments.$.targetReservationId': reservation._id,
            ...(assignment.identifierCorrelationHash || !correlation
              ? {}
              : {
                  'assignments.$.identifierCorrelationHash': correlation.hash,
                  'assignments.$.correlationKeyVersion': correlation.version,
                }),
          },
        },
      );
      assignment.targetReservationId = reservation._id;
    }
  }

  private async recoverApplying(
    operation: AuthIdentifierOperationDocument,
  ): Promise<void> {
    let retryRequired = false;
    for (const assignment of operation.assignments) {
      if (assignment.status === 'applied') {
        continue;
      }
      const reservation = await this.findReservation(operation, assignment);
      const expectedStatus =
        assignment.action === 'release'
          ? AuthIdentifierStatus.Released
          : AuthIdentifierStatus.Active;
      if (
        reservation?.status === expectedStatus &&
        reservation.lastOperationId === operation.operationId
      ) {
        await this.operationModel.updateOne(
          {
            operationId: operation.operationId,
            'assignments.assignmentId': assignment.assignmentId,
            leaseOwner: this.instanceId,
          },
          {
            $set: {
              'assignments.$.status': 'applied',
              'assignments.$.appliedAt': reservation.updatedAt,
            },
          },
        );
        assignment.status = AuthIdentifierAssignmentStatus.Applied;
      } else {
        retryRequired = true;
      }
    }

    await this.transition(
      operation.operationId,
      AuthIdentifierOperationStatus.Applying,
      retryRequired
        ? AuthIdentifierOperationStatus.FailedRetryable
        : AuthIdentifierOperationStatus.Finalizing,
    );
  }

  private async recoverCompensating(
    operation: AuthIdentifierOperationDocument,
  ): Promise<void> {
    let retryRequired = false;
    for (const assignment of [...operation.assignments].reverse()) {
      if (assignment.status === 'compensated') {
        continue;
      }
      if (assignment.status === 'applied') {
        retryRequired = true;
        continue;
      }

      const reservation = await this.findReservation(operation, assignment);
      if (
        !reservation ||
        reservation.pendingOperationId !== operation.operationId
      ) {
        retryRequired = true;
        continue;
      }

      const restoredStatus =
        assignment.action === 'retain'
          ? AuthIdentifierStatus.Conflict
          : assignment.action === 'release'
            ? AuthIdentifierStatus.Active
            : AuthIdentifierStatus.Released;
      await this.identifierModel.updateOne(
        { _id: reservation._id, pendingOperationId: operation.operationId },
        {
          $set: {
            status: restoredStatus,
            lastOperationId: operation.operationId,
          },
          $unset: { pendingOperationId: '', pendingAction: '' },
        },
      );
      await this.operationModel.updateOne(
        {
          operationId: operation.operationId,
          'assignments.assignmentId': assignment.assignmentId,
          leaseOwner: this.instanceId,
        },
        { $set: { 'assignments.$.status': 'compensated' } },
      );
      assignment.status = AuthIdentifierAssignmentStatus.Compensated;
    }

    await this.transition(
      operation.operationId,
      AuthIdentifierOperationStatus.Compensating,
      retryRequired
        ? AuthIdentifierOperationStatus.FailedRetryable
        : AuthIdentifierOperationStatus.Finalizing,
    );
  }

  private async finalize(
    operation: AuthIdentifierOperationDocument,
  ): Promise<void> {
    const failed =
      operation.result?.outcome ===
        AuthIdentifierOperationResultOutcome.Failure ||
      operation.assignments.every((item) => item.status === 'compensated');
    const terminalStatus = failed
      ? AuthIdentifierOperationStatus.FailedTerminal
      : AuthIdentifierOperationStatus.Completed;
    const reasonCategory =
      operation.result?.reasonCategory ??
      (failed
        ? 'identifier-operation-compensated'
        : 'identifier-operation-recovered');
    const eventId =
      await this.securityActivityService.recordIdentifierOperationTerminal({
        operationId: operation.operationId,
        operationType: operation.operationType,
        terminalStatus,
        actor: {
          actorType:
            operation.requestedBy.subjectType === 'member'
              ? SecurityActivityActorType.Member
              : SecurityActivityActorType.Staff,
          actorId: operation.requestedBy.subjectId,
        },
        outcome: failed
          ? SecurityActivityOutcome.Failure
          : SecurityActivityOutcome.Success,
        reasonCategory,
      });

    const cleanupRequired =
      operation.cleanupStatus === AuthIdentifierOperationCleanupStatus.Pending;
    await this.operationModel.findOneAndUpdate(
      {
        operationId: operation.operationId,
        status: AuthIdentifierOperationStatus.Finalizing,
        leaseOwner: this.instanceId,
      },
      [
        {
          $set: {
            status: terminalStatus,
            terminalEventId: eventId,
            terminalEventRecordedAt: '$$NOW',
            completedAt: '$$NOW',
            updatedAt: '$$NOW',
            ...(cleanupRequired
              ? {}
              : {
                  expiresAt: {
                    $dateAdd: {
                      startDate: '$$NOW',
                      unit: 'day',
                      amount: this.retentionDays,
                    },
                  },
                }),
          },
        },
      ],
      { returnDocument: 'after', updatePipeline: true },
    );
  }

  private async cleanup(
    operation: AuthIdentifierOperationDocument,
  ): Promise<void> {
    let remainingCapacity = this.maxAssignments;
    const gated = await this.identifierModel
      .find({ activationGateOperationId: operation.operationId })
      .select({ _id: 1 })
      .limit(remainingCapacity)
      .lean()
      .exec();
    if (gated.length) {
      await this.identifierModel.updateMany(
        { _id: { $in: gated.map((item) => item._id) } },
        {
          ...(operation.status === AuthIdentifierOperationStatus.FailedTerminal
            ? { $set: { status: AuthIdentifierStatus.Released } }
            : {}),
          $unset: { activationGateOperationId: '' },
        },
      );
      remainingCapacity -= gated.length;
    }

    if (remainingCapacity > 0) {
      const batches = await this.repairBatchModel
        .find({
          parentOperationId: operation.operationId,
          expiresAt: { $exists: false },
        })
        .select({ _id: 1 })
        .limit(remainingCapacity)
        .lean()
        .exec();
      if (batches.length) {
        await this.repairBatchModel.updateMany(
          { _id: { $in: batches.map((item) => item._id) } },
          [{ $set: { expiresAt: '$$NOW' } }],
          { updatePipeline: true },
        );
      }
    }

    await this.renewLease(operation.operationId);
    const [gateRemaining, batchRemaining] = await Promise.all([
      this.identifierModel.exists({
        activationGateOperationId: operation.operationId,
      }),
      this.repairBatchModel.exists({
        parentOperationId: operation.operationId,
        expiresAt: { $exists: false },
      }),
    ]);
    if (gateRemaining || batchRemaining) {
      return;
    }

    await this.operationModel.findOneAndUpdate(
      {
        operationId: operation.operationId,
        status: { $in: TERMINAL_STATUSES },
        cleanupStatus: AuthIdentifierOperationCleanupStatus.Pending,
        terminalEventId: { $exists: true },
        terminalEventRecordedAt: { $exists: true },
        leaseOwner: this.instanceId,
      },
      [
        {
          $set: {
            cleanupStatus: AuthIdentifierOperationCleanupStatus.Completed,
            expiresAt: {
              $dateAdd: {
                startDate: '$$NOW',
                unit: 'day',
                amount: this.retentionDays,
              },
            },
            updatedAt: '$$NOW',
          },
        },
      ],
      { returnDocument: 'after', updatePipeline: true },
    );
  }

  private async findReservation(
    operation: AuthIdentifierOperationDocument,
    assignment: AuthIdentifierOperationAssignment,
  ): Promise<AuthIdentifierDocument | null> {
    if (assignment.targetReservationId) {
      return this.identifierModel.findById(assignment.targetReservationId);
    }
    return this.identifierModel.findOne({
      pendingOperationId: operation.operationId,
      subjectType: assignment.subjectType,
      subjectId: assignment.subjectId,
      pendingAction: String(assignment.action) as AuthIdentifierPendingAction,
    });
  }

  private async transition(
    operationId: string,
    from: AuthIdentifierOperationStatus,
    to: AuthIdentifierOperationStatus,
  ): Promise<void> {
    if (from === to) {
      return;
    }
    await this.operationModel.updateOne(
      { operationId, status: from, leaseOwner: this.instanceId },
      { $set: { status: to } },
    );
  }

  private async releaseLease(operationId: string): Promise<void> {
    await this.operationModel.updateOne(
      { operationId, leaseOwner: this.instanceId },
      [
        {
          $set: { leaseExpiresAt: '$$NOW', updatedAt: '$$NOW' },
        },
      ],
      { updatePipeline: true },
    );
  }

  private correlationFor(
    normalizedIdentifier: string,
    requestedVersion?: number,
  ): { hash: string; version: number } | undefined {
    const version =
      requestedVersion ??
      this.configService.get<number>(
        'auth.auditCorrelationKeyRing.currentVersion',
      ) ??
      this.configService.get<number>('auth.auditCorrelationKeyVersion');
    if (!version) {
      return undefined;
    }
    const material = this.keyPolicy.getKeyMaterial(version);
    if (!material) {
      return undefined;
    }
    const key = Buffer.isBuffer(material)
      ? material
      : this.decodeConfiguredSecret(material);
    return {
      hash: createHmac('sha256', key)
        .update('book-library/auth-identifier-reconciliation/v1\0')
        .update(normalizedIdentifier)
        .digest('base64url'),
      version,
    };
  }

  private decodeConfiguredSecret(value: string): Buffer {
    const decoded = Buffer.from(value, 'base64url');
    return decoded.toString('base64url') === value
      ? decoded
      : Buffer.from(value, 'utf8');
  }

  private get leaseSeconds(): number {
    return (
      this.configService.get<number>('auth.identifierLeaseSeconds') ??
      DEFAULT_LEASE_SECONDS
    );
  }

  private get intervalSeconds(): number {
    return (
      this.configService.get<number>(
        'auth.identifierReconciliationIntervalSeconds',
      ) ?? DEFAULT_INTERVAL_SECONDS
    );
  }

  private get batchSize(): number {
    return (
      this.configService.get<number>(
        'auth.identifierReconciliationBatchSize',
      ) ?? DEFAULT_BATCH_SIZE
    );
  }

  private get retentionDays(): number {
    return (
      this.configService.get<number>('auth.identifierOperationRetentionDays') ??
      DEFAULT_RETENTION_DAYS
    );
  }

  private get maxAssignments(): number {
    return (
      this.configService.get<number>(
        'auth.identifierMaxOperationAssignments',
      ) ?? DEFAULT_MAX_ASSIGNMENTS
    );
  }
}

import { Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { SchedulerRegistry } from '@nestjs/schedule';
import { Connection, Types } from 'mongoose';
import {
  createIdentifierModelHarness,
  createStaffModelHarness,
  deferred,
  queryResult,
} from '../../test/support/backend-coverage-fixtures';
import {
  createIdentifierOperation,
  criticalQueryResult,
} from '../../test/support/critical-auth-fixtures';
import { AuthIdentifierReconciliationService } from './auth-identifier-reconciliation.service';
import { AuthIdentifierRepairKeyPolicyService } from './auth-identifier-repair-key-policy.service';
import {
  AuthIdentifierAssignmentAction,
  AuthIdentifierAssignmentStatus,
  AuthIdentifierOperationCleanupStatus,
  AuthIdentifierOperationResultOutcome,
  AuthIdentifierOperationStatus,
  AuthIdentifierOperationType,
} from './schemas/auth-identifier-operation.schema';
import {
  AuthIdentifierPendingAction,
  AuthIdentifierStatus,
  AuthIdentifierSubjectType,
} from './schemas/auth-identifier.schema';

const staffRequester = createStaffModelHarness().document;

function operation(overrides: Record<string, unknown> = {}) {
  return createIdentifierOperation({
    operationId: 'operation-1',
    requestedBy: {
      subjectType: AuthIdentifierSubjectType.Staff,
      subjectId: staffRequester._id.toString(),
    },
    ...overrides,
  });
}

function assignment(overrides: Record<string, unknown> = {}) {
  return {
    assignmentId: 'assignment-1',
    subjectType: AuthIdentifierSubjectType.Member,
    subjectId: 'member-1',
    action: AuthIdentifierAssignmentAction.Claim,
    status: AuthIdentifierAssignmentStatus.Pending,
    ...overrides,
  };
}

describe('AuthIdentifierReconciliationService', () => {
  let operations: any;
  let identifiers: any;
  let batches: any;
  let policy: Pick<
    AuthIdentifierRepairKeyPolicyService,
    'repairWorkerDecision' | 'getKeyMaterial'
  >;
  let events: any;
  let config: ConfigService;
  let service: AuthIdentifierReconciliationService;

  function createReconciliationService(overrides?: {
    scheduler?: SchedulerRegistry;
    connection?: Connection;
    config?: ConfigService;
    operations?: typeof operations;
    identifiers?: typeof identifiers;
    batches?: typeof batches;
  }): AuthIdentifierReconciliationService {
    return new AuthIdentifierReconciliationService(
      overrides?.operations ?? operations,
      overrides?.identifiers ?? identifiers,
      overrides?.batches ?? batches,
      policy as AuthIdentifierRepairKeyPolicyService,
      events,
      overrides?.config ?? config,
      overrides?.scheduler,
      overrides?.connection,
    );
  }

  beforeEach(() => {
    operations = {
      find: jest.fn().mockReturnValue(criticalQueryResult([])),
      findOneAndUpdate: jest.fn().mockResolvedValue(null),
      updateOne: jest.fn().mockResolvedValue({ modifiedCount: 1 }),
    };
    const identifierHarness = createIdentifierModelHarness();
    identifiers = {
      ...identifierHarness.model,
      find: jest.fn().mockReturnValue(criticalQueryResult([])),
      findById: jest.fn().mockResolvedValue(null),
      updateMany: jest.fn().mockResolvedValue({ modifiedCount: 0 }),
      exists: jest.fn().mockResolvedValue(null),
    };
    batches = {
      find: jest.fn().mockReturnValue(criticalQueryResult([])),
      updateMany: jest.fn().mockResolvedValue({ modifiedCount: 0 }),
      exists: jest.fn().mockResolvedValue(null),
    };
    policy = {
      repairWorkerDecision: jest.fn().mockReturnValue({
        allowed: true,
        reason: 'ready',
        requiredVersion: 1,
      }),
      getKeyMaterial: jest.fn().mockReturnValue('audit-key-material'),
    };
    events = {
      recordIdentifierOperationTerminal: jest
        .fn()
        .mockResolvedValue('auth-identifier-operation:operation-1:completed'),
    };
    const values: Record<string, number> = {
      'auth.auditCorrelationKeyRing.currentVersion': 1,
      'auth.identifierLeaseSeconds': 301,
      'auth.identifierReconciliationBatchSize': 2,
      'auth.identifierMaxOperationAssignments': 2,
      'auth.identifierOperationRetentionDays': 91,
    };
    config = { get: (key: string) => values[key] } as ConfigService;
    service = createReconciliationService();
  });

  it('checks a repair key before acquiring a lease and leaves data unchanged when missing', async () => {
    operations.find.mockReturnValue(
      criticalQueryResult([
        operation({
          operationType: AuthIdentifierOperationType.OfflineRepair,
          manifestKeyVersion: 9,
        }),
      ]),
    );
    (policy.repairWorkerDecision as jest.Mock).mockReturnValue({
      allowed: false,
      reason: 'repair-key-required',
      requiredVersion: 9,
    });

    await expect(service.reconcileOnce()).resolves.toMatchObject({
      claimed: 0,
      processed: 0,
      skippedMissingKey: 1,
    });
    expect(operations.findOneAndUpdate).not.toHaveBeenCalled();
    expect(operations.updateOne).not.toHaveBeenCalled();
    expect(identifiers.updateOne).not.toHaveBeenCalled();
  });

  it('claims an offline repair only when policy and key material are available', async () => {
    const offlineRepair = operation({
      operationType: AuthIdentifierOperationType.OfflineRepair,
      manifestKeyVersion: 1,
      status: AuthIdentifierOperationStatus.Completed,
      cleanupStatus: AuthIdentifierOperationCleanupStatus.Completed,
    });
    operations.find.mockReturnValue(criticalQueryResult([offlineRepair]));
    operations.findOneAndUpdate.mockResolvedValue(offlineRepair);

    await expect(service.reconcileOnce()).resolves.toMatchObject({
      examined: 1,
      claimed: 1,
      processed: 1,
      skippedMissingKey: 0,
    });
    expect(operations.findOneAndUpdate).toHaveBeenCalledTimes(1);
    expect(operations.updateOne).toHaveBeenCalledWith(
      {
        operationId: offlineRepair.operationId,
        leaseOwner: expect.any(String),
      },
      [{ $set: { leaseExpiresAt: '$$NOW', updatedAt: '$$NOW' } }],
      { updatePipeline: true },
    );
  });

  it('skips an offline repair when policy allows but key material is absent', async () => {
    const offlineRepair = operation({
      operationType: AuthIdentifierOperationType.OfflineRepair,
      manifestKeyVersion: 1,
    });
    operations.find.mockReturnValue(criticalQueryResult([offlineRepair]));
    (policy.getKeyMaterial as jest.Mock).mockReturnValue(undefined);

    await expect(service.reconcileOnce()).resolves.toEqual({
      examined: 1,
      claimed: 0,
      processed: 0,
      skippedMissingKey: 1,
    });
    expect(operations.findOneAndUpdate).not.toHaveBeenCalled();
    expect(operations.updateOne).not.toHaveBeenCalled();
  });

  it.each([
    [
      'canonical base64url',
      'AQID',
      'lEM1oM_GJ_Uo74k0Uuo-fbm3ITclnSJY35gtRSJFOfg',
    ],
    [
      'literal UTF-8',
      'not base64!',
      'wSOLmzFyV-NqjUmHROCdyQ18-fQ0sMfKBioXPTtkDno',
    ],
  ])(
    'uses the legacy key version and %s material in a public assignment write',
    async (_case, keyMaterial, expectedHash) => {
      const legacyConfig = {
        get: jest.fn((key: string) =>
          key === 'auth.auditCorrelationKeyVersion' ? 7 : undefined,
        ),
      } as unknown as ConfigService;
      const candidate = operation({
        operationId: `operation-legacy-${_case}`,
        assignments: [assignment()],
      });
      const reservationId = new Types.ObjectId();
      operations.find.mockReturnValue(criticalQueryResult([candidate]));
      operations.findOneAndUpdate.mockResolvedValue(candidate);
      identifiers.find.mockReturnValue(
        criticalQueryResult([
          {
            _id: reservationId,
            normalizedIdentifier: 'member@example.test',
            pendingOperationId: candidate.operationId,
            pendingAction: AuthIdentifierPendingAction.Claim,
            subjectType: AuthIdentifierSubjectType.Member,
            subjectId: 'member-1',
          },
        ]),
      );
      (policy.getKeyMaterial as jest.Mock).mockReturnValue(keyMaterial);
      const defaults = createReconciliationService({ config: legacyConfig });

      await expect(defaults.reconcileOnce()).resolves.toMatchObject({
        claimed: 1,
        processed: 1,
      });

      expect(operations.findOneAndUpdate.mock.calls[0][1]).toEqual([
        {
          $set: {
            leaseOwner: expect.any(String),
            leaseExpiresAt: {
              $dateAdd: {
                startDate: '$$NOW',
                unit: 'second',
                amount: 300,
              },
            },
            updatedAt: '$$NOW',
          },
        },
      ]);
      expect(operations.updateOne).toHaveBeenCalledWith(
        expect.objectContaining({
          'assignments.assignmentId': 'assignment-1',
        }),
        expect.objectContaining({
          $set: expect.objectContaining({
            'assignments.$.targetReservationId': reservationId,
            'assignments.$.identifierCorrelationHash': expectedHash,
            'assignments.$.correlationKeyVersion': 7,
          }),
        }),
      );
    },
  );

  it('uses the public terminal write to apply the default retention duration', async () => {
    const defaultConfig = { get: jest.fn() } as unknown as ConfigService;
    const candidate = operation({
      operationId: 'operation-default-retention',
      status: AuthIdentifierOperationStatus.Finalizing,
      cleanupStatus: AuthIdentifierOperationCleanupStatus.NotRequired,
      assignments: [
        assignment({ status: AuthIdentifierAssignmentStatus.Applied }),
      ],
    });
    operations.find.mockReturnValue(criticalQueryResult([candidate]));
    operations.findOneAndUpdate.mockResolvedValue(candidate);
    identifiers.find.mockReturnValue(criticalQueryResult([]));
    const defaults = createReconciliationService({ config: defaultConfig });

    await expect(defaults.reconcileOnce()).resolves.toMatchObject({
      claimed: 1,
      processed: 1,
    });

    expect(
      operations.findOneAndUpdate.mock.calls[1][1][0].$set.expiresAt,
    ).toEqual({
      $dateAdd: {
        startDate: '$$NOW',
        unit: 'day',
        amount: 90,
      },
    });
  });

  it('uses MongoDB time for atomic lease acquisition and renewal', async () => {
    const now = new Date('2026-07-15T00:00:00.000Z');
    jest.useFakeTimers().setSystemTime(now);
    const candidate = operation();
    const candidateCapture: { sort?: unknown; limit?: number } = {};
    operations.find.mockReturnValue(
      criticalQueryResult([candidate], candidateCapture),
    );
    operations.findOneAndUpdate
      .mockResolvedValueOnce(candidate)
      .mockResolvedValueOnce(candidate);

    await service.reconcileOnce();
    await expect(service.renewLease(candidate.operationId)).resolves.toBe(true);

    expect(operations.find).toHaveBeenCalledWith({
      $and: [
        {
          $or: [
            {
              status: {
                $in: [
                  AuthIdentifierOperationStatus.Pending,
                  AuthIdentifierOperationStatus.Applying,
                  AuthIdentifierOperationStatus.Compensating,
                  AuthIdentifierOperationStatus.Finalizing,
                  AuthIdentifierOperationStatus.FailedRetryable,
                ],
              },
            },
            {
              status: {
                $in: [
                  AuthIdentifierOperationStatus.Completed,
                  AuthIdentifierOperationStatus.FailedTerminal,
                ],
              },
              cleanupStatus: AuthIdentifierOperationCleanupStatus.Pending,
            },
          ],
        },
        {
          $or: [
            { leaseExpiresAt: { $exists: false } },
            { leaseExpiresAt: { $lte: new Date(now.getTime() - 5_000) } },
          ],
        },
